public class SchoolPackageStructureDemo { public static void main(String[] args){System.out.println("In the integrated project, classes are grouped into packages:");System.out.println("model - domain records");System.out.println("service - business rules");System.out.println("repository - persistence");System.out.println("ui - user interface");System.out.println("api - interfaces and REST endpoint");System.out.println("exception - application errors");System.out.println("util - shared utilities");} }
